import{_ as n,C as t,o as l,c as h,j as s,a as d,E as a,ak as o}from"./chunks/framework.sV-XtlWr.js";const w=JSON.parse('{"title":"Resource leaks","description":"The browsers, contexts, pages and API request contexts your tests leave open or open for nothing, listed at the end of each run and on its Resources tab, with the line that opened them.","frontmatter":{"title":"Resource leaks","description":"The browsers, contexts, pages and API request contexts your tests leave open or open for nothing, listed at the end of each run and on its Resources tab, with the line that opened them.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/resource-leaks.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/resource-leaks.html"}],["meta",{"property":"og:title","content":"Resource leaks | Piwi Dashboard"}],["meta",{"property":"og:description","content":"The browsers, contexts, pages and API request contexts your tests leave open or open for nothing, listed at the end of each run and on its Resources tab, with the line that opened them."}]]},"headers":[],"relativePath":"features/resource-leaks.md","filePath":"features/resource-leaks.md","lastUpdated":1791120864000}'),c={name:"features/resource-leaks.md"};function p(u,e,f,g,m,k){const r=t("Needs"),i=t("DemoExamples");return l(),h("div",null,[e[0]||(e[0]=s("h1",{id:"resource-leaks",tabindex:"-1"},[d("Resource leaks "),s("a",{class:"header-anchor",href:"#resource-leaks","aria-label":'Permalink to "Resource leaks"'},"​")],-1)),a(r,{reporter:"",fixtures:""}),e[1]||(e[1]=o(`<p>A browser context a test never closes keeps its renderer processes, memory and CPU until the worker shuts down, and every later test on that worker runs next to it. Playwright closes what its own fixtures open; a context, page, browser or API request context a test opens by hand is the test&#39;s to close. The <a href="/guide/capture-fixtures.html">capture fixtures</a> keep a ledger of every one of them, and at the end of the run the reporter lists those left open past the scope that opened them, with the line that did.</p><h2 id="the-summary" tabindex="-1">The summary <a class="header-anchor" href="#the-summary" aria-label="Permalink to &quot;The summary&quot;">​</a></h2><p>The reporter prints it after the last test, before the upload, and adds it to the job summary on GitHub Actions:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Piwi Dashboard] Resources: 3 leaks · 6 idle pages · 1 piling up · 1 handle left in workers</span></span>
<span class="line"><span>[Piwi Dashboard]   leaked   context     tests/cart.spec.ts:12 · 4 contexts · with 4 pages · 4 tests · open until the worker shut down (41.2 s past its test) · 18.3 s of page CPU after its test</span></span>
<span class="line"><span>[Piwi Dashboard]   leaked   page        popup after locator.click at tests/checkout.spec.ts:30 · 2 pages · 2 tests · open 3.1 s past its test</span></span>
<span class="line"><span>[Piwi Dashboard]   leaked   context     tests/admin.spec.ts:8 · beforeAll of &quot;admin&quot; · 1 test · open until the worker shut down (12.0 s past its describe block)</span></span>
<span class="line"><span>[Piwi Dashboard]   piling   listeners   fixture &quot;adminPage&quot; at tests/fixtures.ts:21 · 11 → 31 listeners over 20 tests</span></span>
<span class="line"><span>[Piwi Dashboard]   handle   server      left running in the worker by &quot;mocks the payment API&quot; (tests/pay.spec.ts)</span></span>
<span class="line"><span>[Piwi Dashboard]   idle     page        fixture &quot;page&quot; · 6 pages · 6 tests · set up with consoleCollector (tests/fixtures.ts:40)</span></span>
<span class="line"><span>[Piwi Dashboard] Set leakCheck: &#39;fail&#39; (PIWI_LEAK_CHECK=fail) to fail the tests that leave what they open, or &#39;close&#39; to close it.</span></span></code></pre></div><p>Findings that share a line are grouped: the first one above is the same line leaking in four tests. A leaked context or browser carries the pages open in it, and a page <code>browser.newPage()</code> opened carries the context made for it. At most ten findings are listed; the rest are counted. In Chromium, the fixtures read each page that outlives its test over the DevTools protocol, so a leak also says how much CPU its pages&#39; main threads used after their test, from half a second. The <a href="./cpu-memory-disk.html">CPU, memory &amp; disk</a> panel follows, with what the whole run cost the machine.</p><h2 id="what-it-reports" tabindex="-1">What it reports <a class="header-anchor" href="#what-it-reports" aria-label="Permalink to &quot;What it reports&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Finding</th><th>What it means</th><th>The usual fix</th></tr></thead><tbody><tr><td><strong>leaked</strong>, past its test</td><td>Opened by the test body or its <code>beforeEach</code>/<code>afterEach</code>, and still open when the test ended. Nothing in the same file closed it later.</td><td><code>close()</code> or <code>dispose()</code> before the test ends, or <code>await using</code></td></tr><tr><td><strong>leaked</strong>, past its describe block</td><td>Opened in a <code>beforeAll</code> (or an <code>afterAll</code>) and still open once the tests of its describe block ran.</td><td>Close it in <code>afterAll</code></td></tr><tr><td><strong>piling up</strong></td><td>A page or context that lives across tests, from a worker-scoped fixture for example, whose open pages, listeners or route handlers grew over at least three tests and never came back down</td><td>Remove the listener or route the test adds, or close the popups it opens</td></tr><tr><td><strong>handle</strong></td><td>A server or file watcher a test started in the worker process and left running for the next test</td><td>Close it in the test or an <code>afterEach</code></td></tr><tr><td><strong>idle</strong></td><td>A page opened and never used: no navigation, content, script or locator. The detail names the fixtures of yours that set it up.</td><td>Drop the <code>page</code> argument, or the fixture that asks for it</td></tr><tr><td><strong>probable</strong></td><td>From a test that ran without the fixtures, counted from its steps: more browsers or contexts opened than closed in a spec file</td><td>Use the fixtures for exact findings</td></tr></tbody></table><p>What is never reported:</p><ul><li>what a <strong>worker-scoped fixture</strong> holds: it lives as long as the worker by design;</li><li>a context Playwright <strong>reuses</strong> on purpose (UI mode, <code>--reuse-context</code>);</li><li>an object <strong>handed on</strong> to a later test, or a <code>beforeAll</code> object an <code>afterAll</code> closes, within the same file;</li><li>what a <strong>failed test</strong> left open: Playwright shuts its worker down right after it.</li></ul><h2 id="fail-or-close-leaks" tabindex="-1">Fail or close leaks <a class="header-anchor" href="#fail-or-close-leaks" aria-label="Permalink to &quot;Fail or close leaks&quot;">​</a></h2><p><code>leakCheck</code> (or <code>PIWI_LEAK_CHECK</code>) decides what the fixtures do with an object a test opened itself and left open:</p><ul><li><code>&#39;report&#39;</code>, the default, only lists it;</li><li><code>&#39;fail&#39;</code> also fails the test, naming each object and its line;</li><li><code>&#39;close&#39;</code> closes it when the test ends, and lists it as <em>closed by Piwi</em>.</li></ul><div class="language-typescript vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">typescript</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wrapConfig</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(config, { projectName: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;my-project&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, leakCheck: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;fail&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> })</span></span></code></pre></div><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Error: Piwi: this test left one object open:</span></span>
<span class="line"><span>  - a context opened at tests/cart.spec.ts:12, with 1 page</span></span>
<span class="line"><span>Close each before the test ends (await using, close() or dispose()), or set PIWI_LEAK_CHECK=report to only list them.</span></span></code></pre></div><p>A <code>beforeAll</code> object, and what a fixture opens, are only ever reported. Each test is judged when it ends, so a test that hands what it opened to the next one fails under <code>&#39;fail&#39;</code> and loses it under <code>&#39;close&#39;</code>: open such objects in <code>beforeAll</code> and close them in <code>afterAll</code>.</p><p>The ledger is on whenever the fixtures are. Turn it off with <code>captureResources: false</code> (or <code>PIWI_CAPTURE_RESOURCES=false</code>). Like every fixture option, set both through <a href="/guide/reporter.html#installing-via-wrapconfig"><code>wrapConfig</code></a> or their variable: the test workers never see a plain reporter entry&#39;s options.</p><h2 id="in-the-dashboard" tabindex="-1">In the dashboard <a class="header-anchor" href="#in-the-dashboard" aria-label="Permalink to &quot;In the dashboard&quot;">​</a></h2><p>A run whose reporter sent findings shows a <strong>Resources</strong> tab:</p><ul><li>the counts of each kind of finding, the CPU the run&#39;s processes used and the machine&#39;s peak memory;</li><li>the findings, each with the line or fixture that opened the object, a click from your editor;</li><li>a pointer to each worker&#39;s open pages over the run, drawn on the run&#39;s <a href="./cpu-memory-disk.html#in-the-dashboard">Timeline tab</a> above the worker rows: a leak climbs test after test, a clean worker stays flat;</li><li>the machine each shard ran on, from the <a href="./cpu-memory-disk.html#in-the-dashboard">CPU, memory &amp; disk</a> panel;</li><li>the <strong>costliest tests</strong>, by the CPU of their worker and browser processes, with the pages each found already open.</li></ul><p>The execution page&#39;s Performance tab shows what that one test cost and what it left open. A project that declines the <strong>Resources</strong> capability on the Setup page hides both, and the reporter&#39;s summary stays as it is.</p><h2 id="in-ci" tabindex="-1">In CI <a class="header-anchor" href="#in-ci" aria-label="Permalink to &quot;In CI&quot;">​</a></h2><p>Each finding keeps a history: the run it was first seen in and the runs that showed it. A leak is fixed once five full runs of the default branch, with the fixtures on, came without it, and reopens if it shows again. A leak that an edit above its line moved keeps its history. On the Resources tab each finding says whether it is new to the base branch (the pull request&#39;s target, else the default branch), or since which run it has been there.</p><p>Three places read it:</p><ul><li><a href="/guide/ci.html#blocking-a-merge"><code>piwi gate</code></a>: <code>--max-leaks &lt;n&gt;</code> fails when the run left more than <code>n</code> objects open, counted per opening line; <code>--max-new-leaks &lt;n&gt;</code>, when more than <code>n</code> were never seen on the base branch. A run that sent no resource report fails either rule rather than passing on silence.</li><li>The <a href="./pr-feedback.html">pull-request comment</a> lists each leak the branch introduces under <strong>Left open by this change</strong>.</li><li>Agents read <code>list_resource_findings</code> and <code>get_resource_profile</code> over <a href="/reference/mcp-tools.html">MCP</a>.</li></ul><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> @piwitests/reporter</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> gate</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --max-new-leaks</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span></span></code></pre></div><h2 id="cost" tabindex="-1">Cost <a class="header-anchor" href="#cost" aria-label="Permalink to &quot;Cost&quot;">​</a></h2><p>The ledger listens to the calls Playwright already reports and does its bookkeeping at the end of each test, adding nothing to the steps or the trace. In Chromium, a page still open at the end of a test is read over the DevTools protocol: about 20 ms the first time, to open a session, then a couple of milliseconds per test while it stays open. A test that started a server waits one timer tick more at its end, so the server&#39;s count settles.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li>The dashboard keeps the first 100 findings of each run, most severe first.</li><li><strong>Playwright internals.</strong> The ledger reads Playwright&#39;s instrumentation hooks, the runner&#39;s current test and fixture, and a few private fields (<code>_routes</code>, <code>_ownerPage</code>, <code>_opener</code>). The Playwright versions the reporter supports have them all, and each is checked before use: without the hooks the ledger stays off.</li><li>An object kept in a module variable on purpose and closed by another spec file reads as leaked.</li><li>A page used only through calls the ledger does not count, a screenshot of a blank page for example, reads as idle.</li><li>Node handles are servers and file watchers only: sockets, timers and child processes move on every test, Playwright&#39;s own included.</li></ul><h2 id="try-it-in-the-demo" tabindex="-1">Try it in the demo <a class="header-anchor" href="#try-it-in-the-demo" aria-label="Permalink to &quot;Try it in the demo&quot;">​</a></h2><p>The <a href="https://piwitests.dev/demo/" target="_blank" rel="noreferrer">live demo</a> holds a leaky run, and its run simulator replays one: pick <strong>Leaky run</strong>.</p>`,31)),a(i),e[2]||(e[2]=o('<h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/guide/capture-fixtures.html">Capture fixtures</a>: what else the fixtures record</li><li><a href="/reference/reporter-options.html#what-gets-captured">Reporter options</a>: <code>captureResources</code> and <code>leakCheck</code></li><li><a href="./cpu-memory-disk.html">CPU, memory &amp; disk</a>: what the whole run cost the machine</li><li><a href="./slow-tests.html">Slow tests &amp; wasted time</a>: where the suite&#39;s time goes</li></ul>',2))])}const y=n(c,[["render",p]]);export{w as __pageData,y as default};
